import math
from wire.codec import encode, decode, CodecError
recs=[{"ts":1,"sensor_id":2,"value":-0.0,"flags":3}]
d=encode(recs); out=decode(d)
print("len", len(d), "neg zero sign kept:", math.copysign(1, out[0]["value"]) == -1.0)
bad=bytearray(d); bad[12]^=0x01
try: decode(bytes(bad)); print("FAIL: corruption undetected")
except CodecError as e: print("corruption detected:", e)
try: decode(d+b"\x00"); print("FAIL")
except CodecError as e: print("extra bytes detected:", e)
try: encode([{"ts":-1,"sensor_id":0,"value":0.0,"flags":0}]); print("FAIL")
except CodecError as e: print("range check:", e)
EOF
